import { IAutoMovieMeshGeometry } from "./IAutoMovieMeshGeometry";
import { IAutoMoviePrimitiveGeometry } from "./IAutoMoviePrimitiveGeometry";

/**
 * The geometry of one model part: either a compact parametric primitive or explicit triangle data.
 *
 * Discriminated on `type` so the two paths the project cares about are explicit: `primitive` is a bounded recipe with named dimensions, while `mesh` is explicit data that may be imported, baked, or generated by a deterministic named function. Both render to triangles downstream. Provenance belongs to {@link AutoMovieAssetOrigin} at the model level, not to this representation discriminator.
 *
 * @evidence contracts/common.md#principled-implementation The type discriminator separates a bounded primitive recipe from explicit triangle attributes; viewer construction and geometry consumers narrow this union before tessellating or reading mesh buffers.
 * @evidence contracts/common.md#clear-and-simple-design Two arms reuse the shape and mesh records without optional buffers on a primitive or optional dimensions on a mesh; model origin independently carries provenance.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Mesh representation does not imply import or permit transcribed content; deterministic production generators can supply explicit triangles through the same arm.
 * @evidence contracts/common.md#meaningful-documentation Explains both representations, their common triangle rendering path, and why provenance belongs to the model rather than the geometry discriminator.
 * @author Samchon
 */
export type IAutoMovieGeometry =
  | IAutoMoviePrimitiveGeometry
  | IAutoMovieMeshGeometry;
